require __DIR__.'/includes/bootstrap.php';require_admin();require __DIR__.'/includes/layout.php';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=post_string('full_name',120);$email=strtolower(post_string('email',190));$current=(string)($_POST['current_password']??'');$new=(string)($_POST['new_password']??'');$q=$pdo->prepare('SELECT password_hash FROM admins WHERE id=?');$q->execute([$_SESSION['admin_id']]);$hash=$q->fetchColumn();$errors=[];if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='Enter a valid name and email.';if(!password_verify($current,$hash))$errors[]='Your current password is incorrect.';if($new!==''&&strlen($new)<12)$errors[]='New passwords must contain at least 12 characters.';if(!$errors){try{$sql='UPDATE admins SET full_name=?,email=?'.($new!==''?',password_hash=?':'').' WHERE id=?';$args=[$name,$email];if($new!=='')$args[]=password_hash($new,PASSWORD_DEFAULT);$args[]=$_SESSION['admin_id'];$pdo->prepare($sql)->execute($args);$_SESSION['admin_name']=$name;audit($pdo,'admin.settings_updated','admin',(int)$_SESSION['admin_id']);flash('success','Account settings updated.');redirect('settings.php');}catch(PDOException $e){$errors[]='That email is already assigned to another administrator.';}}}
